CREATE TABLE series (
  id INT IDENTITY(1,1) NOT NULL,
  handle NVARCHAR(20) NOT NULL,
  parent_id INT NULL,
  CONSTRAINT series_pkey PRIMARY KEY (id),
  CONSTRAINT series_handle_uq UNIQUE (handle),
  CONSTRAINT series_parent_id_fkey FOREIGN KEY (parent_id) REFERENCES series (id)
);

CREATE TABLE books (
  id BIGINT IDENTITY(1,1) NOT NULL,
  title NVARCHAR(120) NOT NULL,
  tags NVARCHAR(MAX) NOT NULL DEFAULT N'[]', -- an array stored as JSON
  grid NVARCHAR(MAX) NULL, -- an array stored as JSON
  colors NVARCHAR(MAX) NULL, -- an array stored as JSON
  color NVARCHAR(50) NOT NULL DEFAULT N'red',
  price DECIMAL(8, 2) NOT NULL DEFAULT 9.99,
  settings NVARCHAR(MAX) NOT NULL DEFAULT N'{"theme":"dark","tabs":[1,2]}',
  published_on DATE NOT NULL DEFAULT (CAST(SYSUTCDATETIME() AS DATE)),
  opens_at TIME NULL,
  released_at DATETIME2 NULL DEFAULT '2020-01-02T03:04:05.000',
  pages INT NOT NULL DEFAULT 100,
  ratio FLOAT NOT NULL DEFAULT 0.5,
  in_print BIT NOT NULL DEFAULT 1,
  notes NVARCHAR(MAX) NULL,
  [window] NVARCHAR(255) NULL, -- range stored as text
  extra NVARCHAR(MAX) NULL, -- hstore stored as JSON
  read_time BIGINT NULL, -- duration in microseconds
  cover VARBINARY(MAX) NULL,
  author_id UNIQUEIDENTIFIER NOT NULL,
  editor_id UNIQUEIDENTIFIER NULL,
  series_handle NVARCHAR(20) NULL,
  CONSTRAINT books_pkey PRIMARY KEY (id),
  CONSTRAINT books_tags_check CHECK (ISJSON(tags) = 1),
  CONSTRAINT books_grid_check CHECK (ISJSON(grid) = 1),
  CONSTRAINT books_colors_check CHECK (ISJSON(colors) = 1),
  CONSTRAINT books_color_check CHECK (color IN (N'red', N'green')),
  CONSTRAINT books_settings_check CHECK (ISJSON(settings) = 1),
  CONSTRAINT books_extra_check CHECK (ISJSON(extra) = 1),
  CONSTRAINT books_series_handle_fkey FOREIGN KEY (series_handle) REFERENCES series (handle) ON DELETE SET NULL
);
CREATE UNIQUE INDEX books_title_author_id_key ON books (title, author_id);
CREATE INDEX books_published_idx ON books (published_on);

CREATE TABLE authors (
  id UNIQUEIDENTIFIER NOT NULL DEFAULT NEWID(),
  handle NVARCHAR(30) NOT NULL,
  favourite_book_id INT NULL,
  latest_book_id BIGINT NULL,
  CONSTRAINT authors_pkey PRIMARY KEY (id),
  CONSTRAINT authors_handle_key UNIQUE (handle),
  CONSTRAINT authors_latest_book_id_fkey FOREIGN KEY (latest_book_id) REFERENCES books (id)
);

CREATE TABLE audiobooks (
  minutes INT NOT NULL,
  book_ptr_id BIGINT NOT NULL,
  CONSTRAINT audiobooks_pkey PRIMARY KEY (book_ptr_id),
  CONSTRAINT audiobooks_book_ptr_id_fkey FOREIGN KEY (book_ptr_id) REFERENCES books (id) ON DELETE CASCADE
);

CREATE TABLE index_rows (
  id INT IDENTITY(1,1) NOT NULL,
  [sql] NVARCHAR(255) NULL,
  class NVARCHAR(255) NULL,
  [table] INT NULL,
  CONSTRAINT index_rows_pkey PRIMARY KEY (id),
  CONSTRAINT index_rows_table_fkey FOREIGN KEY ([table]) REFERENCES series (id)
);

CREATE TABLE tagged (
  id BIGINT IDENTITY(1,1) NOT NULL,
  CONSTRAINT tagged_pkey PRIMARY KEY (id)
);

CREATE TABLE tagged_books (
  id INT IDENTITY(1,1) NOT NULL,
  tagged_id BIGINT NOT NULL,
  book_id BIGINT NOT NULL,
  CONSTRAINT tagged_books_pkey PRIMARY KEY (id),
  CONSTRAINT tagged_books_tagged_id_fkey FOREIGN KEY (tagged_id) REFERENCES tagged (id) ON DELETE CASCADE,
  CONSTRAINT tagged_books_book_id_fkey FOREIGN KEY (book_id) REFERENCES books (id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX tagged_books_tagged_id_book_id_key ON tagged_books (tagged_id, book_id);

